{"file_text": "@* Step 5: Review & Submit *@

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h3>Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-section__header">
                <h3>Personal Information</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-list">
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h3>Work History</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <div class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h3>References</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="review-reference">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <div>@reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"• {reference.Phone}" : "")</div>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        <div class="step-actions">
            <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-primary btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

