private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

private async Task Update(WorkEntry updated)
{
    await OnChanged.InvokeAsync(updated);
}

private async Task ToggleCurrent(bool isCurrent)
{
    var updated = isCurrent
        ? Entry with { EndDate = null }
        : Entry with { EndDate = DateTime.Today };
    await OnChanged.InvokeAsync(updated);
}

arguments.new_str:
private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

private string StartDateString => Entry.StartDate.ToString("yyyy-MM-dd");
private string? EndDateString => Entry.EndDate?.ToString("yyyy-MM-dd");

private async Task Update(WorkEntry updated)
{
    await OnChanged.InvokeAsync(updated);
}

private async Task HandleStartDateChange(ChangeEventArgs e)
{
    var value = (string?)e.Value;
    if (!string.IsNullOrEmpty(value) && DateTime.TryParse(value, out var date))
    {
        await Update(Entry with { StartDate = date });
    }
}

private async Task HandleEndDateChange(ChangeEventArgs e)
{
    var value = (string?)e.Value;
    if (string.IsNullOrEmpty(value))
    {
        await Update(Entry with { EndDate = null });
    }
    else if (DateTime.TryParse(value, out var date))
    {
        await Update(Entry with { EndDate = date });
    }
}

private async Task HandleCurrentToggle(ChangeEventArgs e)
{
    var isCurrent = (bool?)e.Value ?? false;
    var updated = isCurrent
        ? Entry with { EndDate = null }
        : Entry with { EndDate = DateTime.Today };
    await Update(updated);
}

